import { DropdownItem } from "#core/ui/components/fxs-dropdown.js";
import ContextManager, { PushProperties } from "#core/ui/context-manager/context-manager.js";

export type GameCoreOptionCategory = "sound" | "graphics" | "application" | "network" | "configuration";

export enum OptionType {
	/**
	 * Editor is a button that opens an editor for the option.
	 */
	Editor,
	Checkbox,
	Dropdown,
	Slider,
	Stepper,
	Switch,
}

export enum CategoryType {
	Accessibility = "accessibility",
	Audio = "audio",
	Game = "game",
	Graphics = "graphics",
	Input = "input",
	System = "system",
	Interface = "interface",
}

type NonEditorOption = Exclude<OptionInfo, { type: OptionType.Editor }>;
/**
 * OptionInitHandler should read the option's value from its source and set the OptionInfo's currentValue field.
 */
export type OptionInitHandler<O extends NonEditorOption = NonEditorOption> = (optionInfo: O) => void;
/**
 * OptionUpdateHandler is called when the user changes the option's value.
 */
export type OptionUpdateHandler<O extends NonEditorOption = NonEditorOption> = (
	optionInfo: O,
	value: Exclude<O["currentValue"], undefined>,
) => void;
/**
 * EditorOptionActivateHandler is called when the user activates the editor button.
 *
 * The return value is optionally used to determine whether or not the editor should be opened.
 */
export type EditorOptionActivateHandler = () => boolean | undefined;

/**
 * OptionRestoreHandler is called when the user cancel's their changes.
 *
 * It should read in the configuration from the source and apply it to the UI.
 * This is used for configuration options where GameCore holds the value, but the value must be realized within the UI (e.g., UI scale).
 */
export type OptionRestoreHandler<O extends OptionInfo = OptionInfo> = (optionInfo: O) => void;

export type OptionCategoryGroup =
	| "advanced"
	| "advisors"
	| "autosaves"
	| "camera"
	| "controls"
	| "extras"
	| "gamepad"
	| "general"
	| "mouse"
	| "subtitles"
	| "tooltip"
	| "timeofday"
	| "touch"
	| "tutorial"
	| "volume";
export type OptionValue = string | number | boolean;

interface Option<Type extends OptionType, Value extends OptionValue> {
	/** category determines what tab the option can be found under. */
	category: CategoryType;

	currentValue?: Value;

	/**
	 * group is used to render related options in the same category together.
	 */
	group?: OptionCategoryGroup;
	type: Type;

	/**
	 * id is used to identify the option in the backing data and in the UI.
	 */
	id: string;

	/**
	 * label is the localization key for the option's label
	 */
	label: string;

	/**
	 * description is the localization key for the tooltip text
	 */
	description?: string;
	isDisabled?: boolean;
	isHidden?: boolean;

	initListener?: Type extends OptionType.Editor ? never : OptionInitHandler;
	updateListener?: Type extends OptionType.Editor ? never : OptionUpdateHandler;
	restoreListener?: OptionRestoreHandler;

	forceRender?: () => void;
}

export type CheckboxInfo = Option<OptionType.Checkbox, boolean>;
export type AdvancedCheckboxInfo = CheckboxInfo & {
	optionSet: string;
	optionType: string;
	optionName: string;
	originalValue?: boolean;
};

export type SwitchInfo = Option<OptionType.Switch, boolean>;

export type StepperInfo = Option<OptionType.Stepper, number> & {
	min?: number;
	max?: number;
	steps?: number;
	originalValue?: number;
	formattedValue?: string;
};

export type SliderInfo = Option<OptionType.Slider, number> & {
	min?: number;
	max?: number;
	steps?: number;
	originalValue?: number;
	formattedValue?: string;

	/** sliderValue is the text representation of the slider value. */
	sliderValue?: HTMLElement;
};

export type EditorInfo = Option<OptionType.Editor, never> & {
	/** caption is the loc string used on the button which opens the editor */
	caption?: string;

	/**
	 * editorTagName is the tagname of the custom element to create when the button for this option in clicked.
	 *
	 * Add your custom element to the HTMLElementTagNameMap interface via declaration merging.
	 */
	editorTagName: keyof HTMLElementTagNameMap;
	pushProperties?: PushProperties<never, object>;

	activateListener?: EditorOptionActivateHandler;
};

export type DropdownInfo = Option<OptionType.Dropdown, number> & {
	selectedItemIndex?: number;
	dropdownItems?: DropdownItem[];
	originalValue?: number;
};

export type OptionInfo =
	| EditorInfo
	| CheckboxInfo
	| AdvancedCheckboxInfo
	| DropdownInfo
	| SliderInfo
	| StepperInfo
	| SwitchInfo;

class OptionsModel {
	/** Backing data and callback for all the options across all the sections.  */
	private Options = new Map<string, OptionInfo>();

	/** Pending options, can be modified and applied externally */
	public graphicsOptions = GraphicsOptions.getCurrentOptions();
	public supportedOptions = GraphicsOptions.getSupportedOptions();

	// Consider removing these counts and tracking separately in each Option instance
	/** Reference count of options that have changed and aren't back to their original value */
	private changeRefCount = 0;

	/** Reference count of options that need a reload and aren't back to their original value */
	public needReloadRefCount = 0;

	/** Reference count of options that need a reload and aren't back to their original value */
	public needRestartRefCount = 0;

	/** Track if changing options means explicit input refresh needs to occur.  (Different meanings on the C++ side based on platform.) */
	public inputRefreshRequired = false;

	private optionsInitCallbacks: (() => void)[] = [];
	private optionsReInitCallbacks: (() => void)[] = [];
	private optionsChangedCallbacks: (() => void)[] = [];

	constructor() {
		engine.whenReady.then(() => {
			const playerProfileChangedListener = () => {};
			engine.on("PlayerProfileChanged", playerProfileChangedListener); //TODO: wire this up to something legit.
			// This is called when the available graphics options change, typically as a result of docking/undocking a Switch 2.
			engine.on("GraphicsOptionsChanged", () => {
				this.graphicsOptions = GraphicsOptions.getCurrentOptions();
				this.supportedOptions = GraphicsOptions.getSupportedOptions();
				this.reInitOptions();
			});
		});
	}

	get data() {
		return this.Options;
	}

	get supportsGraphicOptions(): boolean {
		return this.supportedOptions.profiles.length != 0;
	}

	get showAdvancedGraphicsOptions(): boolean {
		return this.supportedOptions.canShowAdvancedGraphicsOptions;
	}

	get canUseMetalFx() {
		return this.supportedOptions.canUseMetalFx;
	}
	get showCustomGraphicsProfile(): boolean {
		return this.supportedOptions.canShowCustomGraphicsProfile;
	}

	public incRefCount(): number {
		return this.changeRefCount++;
	}

	public init() {
		this.optionsInitCallbacks.forEach((callback) => callback());
		this.optionsInitCallbacks = [];

		this.updateHiddenOptions();
	}
	/**
	 * Adds a callback to be executed when the options are initialized.
	 *
	 * an init callback is a function that adds options to the model (i.e., calls addOption)
	 */
	public addInitCallback(callback: () => void) {
		if (this.optionsReInitCallbacks.length && !this.optionsInitCallbacks.length) {
			throw new Error("Options already initialized, cannot add init callback");
		}

		this.optionsInitCallbacks.push(callback);

		// Also add this to the re-init list so we have it in case we need to re-init the options.
		this.optionsReInitCallbacks.push(callback);
	}

	/**
	 * Adds a callback to be executed when the options are changed by the engine.
	 */
	public addChangedCallback(callback: () => void) {
		this.optionsChangedCallbacks.push(callback);
	}

	/**
	 * Removes all options changed callbacks.
	 */
	public clearChangedCallbacks() {
		this.optionsChangedCallbacks = [];
	}

	/**
	 * Set up to make the options screen rebuild from the engine data next time it opens.
	 */
	public reInitOptions() {
		this.Options.clear();
		// optionsInitCallbacks is cleared after it's run once since the options are then cached
		// and don't need to be rebuilt.  In this case, we just cleared the cache and want to force
		// the options to be rebuilt, so populate the init callback from where we saved it.
		this.optionsInitCallbacks = this.optionsReInitCallbacks;
		// Call things that want to know that the options have changed (should only be the options screen itself).
		this.optionsChangedCallbacks.forEach((callback) => callback());
		// Having notified everyone, clear the list.  The screen will re-add itself the next time it needs to.
		this.optionsChangedCallbacks = [];
	}

	/**
	 * Add a new option to the options screen.
	 */
	public addOption(info: OptionInfo) {
		switch (info.type) {
			case OptionType.Stepper:
				info.currentValue ??= 0;
				info.min ??= 0;
				info.max ??= 100;
				break;

			case OptionType.Dropdown:
				// nothing here yet
				break;

			case OptionType.Checkbox:
				info.currentValue ??= false;
				break;

			case OptionType.Slider:
				info.min ??= 0;
				info.max ??= 1;
				info.steps ??= 0;
				break;

			case OptionType.Editor:
				break;
		}

		this.Options.set(info.id, info);
		info.initListener?.(info);
	}

	/**
	 * Create a checkpoint for sound and configuration options
	 */
	public saveCheckpoints() {
		Configuration.getUser().saveCheckpoint();
		Sound.volumeSetCheckpoint();
	}

	/**
	 * Save all categories to disk
	 */
	public commitOptions(category?: GameCoreOptionCategory) {
		switch (category) {
			case "sound":
				Sound.volumeWriteSettings();
				break;
			case "graphics":
				GraphicsOptions.applyOptions(this.graphicsOptions);
				break;
			case "application":
				UI.commitApplicationOptions();
				break;
			case "network":
				UI.commitNetworkOptions();
				break;
			case "configuration":
				Configuration.getUser().saveCheckpoint();
				break;
			default:
				Sound.volumeWriteSettings();
				GraphicsOptions.applyOptions(this.graphicsOptions);
				UI.commitApplicationOptions();
				UI.commitNetworkOptions();
				Configuration.getUser().saveCheckpoint();
		}

		// If a reload is requested only perform if in the shell or, if in game, a non-multiplayer game.
		if (this.isUIReloadRequired()) {
			if (!UI.isInGame() || !UI.isMultiplayer()) {
				UI.refreshPlayerColors();
				UI.reloadUI();
			}
		}

		this.changeRefCount = 0;
		this.needReloadRefCount = 0;
		this.needRestartRefCount = 0;
	}

	/**
	 * default restores most settings to their engine-defined default values.
	 */
	public resetOptionsToDefault() {
		// TODO when in-game, this function currently has a few issues:
		//  - colorblindness changes only work for some things in-game, requires a reload to apply fully
		//  - graphics options will currently not be reset in-game, it should work when possible:
		//      - texture detail and asset quality require a reload to work properly
		//      - graphics profile can only be changed if it would not modify those two
		//      - certain settings are not set to defaults, like GPU selection and window mode
		const previousAudioIdx = Locale.getCurrentAudioLanguageOption();
		const previousDisplayIdx = Locale.getCurrentDisplayLanguageOption();

		UI.defaultApplicationOptions();
		UI.defaultAudioOptions();
		UI.defaultUserOptions();
		UI.defaultTutorialOptions();

		if (!UI.isInGame()) {
			this.graphicsOptions = GraphicsOptions.getDefaultOptions();
			GraphicsOptions.applyOptions(this.graphicsOptions);
		}

		Sound.volumeSetMaster(Sound.volumeGetMaster());
		Sound.volumeSetMusic(Sound.volumeGetMusic());
		Sound.volumeSetSFX(Sound.volumeGetSFX());
		Sound.volumeSetUI(Sound.volumeGetUI());
		Sound.volumeSetCinematics(Sound.volumeGetCinematics());
		Sound.volumeSetVoice(Sound.volumeGetVoice());
		Sound.volumeWriteSettings();

		UI.commitApplicationOptions();
		UI.commitNetworkOptions();

		if (UI.isInGame()) {
			if (this.isUIReloadRequired() && !UI.isMultiplayer()) {
				UI.refreshPlayerColors();
				UI.reloadUI();
			}
		}

		this.changeRefCount = 0;
		this.needReloadRefCount = 0;
		this.needRestartRefCount = 0;

		const currentAudioIdx = Locale.getCurrentAudioLanguageOption();
		const currentDisplayIdx = Locale.getCurrentDisplayLanguageOption();
		const didChangeLanguage = currentAudioIdx !== previousAudioIdx || currentDisplayIdx !== previousDisplayIdx;
		if (didChangeLanguage) {
			this.needRestartRefCount++;
		}
	}

	/**
	 * restore resets all categories to their on disk values
	 */
	public restore(category?: GameCoreOptionCategory) {
		switch (category) {
			case "sound":
				Sound.volumeRestoreCheckpoint();
				break;
			case "graphics":
				this.graphicsOptions = GraphicsOptions.getCurrentOptions();
				break;
			case "application":
				UI.revertApplicationOptions();
				break;
			case "network":
				UI.revertNetworkOptions();
				break;
			case "configuration":
				Configuration.getUser().restoreCheckpoint();
				break;
			default:
				Sound.volumeRestoreCheckpoint();
				UI.revertApplicationOptions();
				UI.revertNetworkOptions();
				Configuration.getUser().restoreCheckpoint();
				this.graphicsOptions = GraphicsOptions.getCurrentOptions();

				// we need to do some extra to re-sync the touch/tap delay across the places using it
				ContextManager.updateClickDuration();
		}

		this.changeRefCount = 0;
		this.needReloadRefCount = 0;
		this.needRestartRefCount = 0;

		for (const option of this.Options.values()) {
			option.restoreListener?.(option);
			option.initListener?.(option);
		}
	}

	public hasChanges() {
		return this.changeRefCount > 0;
	}

	/**
	 * Check if the changed options will cause the UI to reload.
	 * @returns true if applying the options changes will reload the UI, false otherwise
	 */
	public isUIReloadRequired() {
		return this.needReloadRefCount > 0;
	}

	/**
	 * Check if the pending options require a restart.
	 * @returns true if applying the pending options will require a restart, false otherwise
	 */
	public isRestartRequired() {
		if (this.needRestartRefCount > 0) return true;

		// Show popup only if settings are actually different, they could have been changed back
		const currentOptions = GraphicsOptions.getCurrentOptions();
		return (
			this.graphicsOptions.deviceID != currentOptions.deviceID || this.graphicsOptions.hdr != currentOptions.hdr
		);
	}

	/**
	 * Does some explicit refresh of the UI input system need to occur?
	 */
	public isInputRefreshRequired() {
		return this.inputRefreshRequired;
	}

	private updateHiddenOptions() {
		const crossplayOption = this.Options.get("option-crossplay");
		if (crossplayOption != undefined) {
			crossplayOption.isHidden = !Network.hasCrossPlayPrivilege();
		}
	}
}

export const Options = new OptionsModel();
